const body = $json.body ?? $json;

const phoneRaw =
  body.phone ??
  body.from ??
  body.caller ??
  body.customer_phone ??
  '';

let rawPhone = String(phoneRaw).trim();

// Normalize common international 00 prefix
if (rawPhone.startsWith('00')) {
  rawPhone = '+' + rawPhone.slice(2);
}

let phoneDigits = rawPhone.replace(/\D/g, '');

let phone = '';

if (rawPhone.startsWith('+')) {

  // Already international format
  if (phoneDigits.length >= 10 && phoneDigits.length <= 15) {
    phone = `+${phoneDigits}`;
  }

} else if (phoneDigits.length === 10) {

  // India default
  phone = `+91${phoneDigits}`;

} else if (
  phoneDigits.length === 11 &&
  phoneDigits.startsWith('0')
) {

  phone = `+91${phoneDigits.slice(1)}`;

} else if (
  phoneDigits.length >= 11 &&
  phoneDigits.length <= 15
) {

  phone = `+${phoneDigits}`;
}

const transcript =
  String(
    body.transcript ??
    body.message ??
    body.text ??
    ''
  )
  .trim()
  .slice(0, 8000);

const providerEventId =
  String(
    body.call_sid ??
    body.callSid ??
    body.message_id ??
    body.event_id ??
    ''
  )
  .trim();

const timestampHint =
  String(
    body.timestamp ??
    body.created_at ??
    body.createdAt ??
    ''
  )
  .trim();

const fallbackKey =
  `fallback:${phone}|${transcript.slice(0, 300)}|${
    timestampHint || Math.floor(Date.now() / 30000)
  }`;

const eventKey =
  providerEventId || fallbackKey;

const correlationId = eventKey;

return [{
  json: {
    correlationId,

    providerEventId:
      providerEventId || fallbackKey,

    eventKey,

    lockKey:
      'omni:lock:' + eventKey,

    completedKey:
      'omni:completed:' + eventKey,

    receivedAt:
      new Date().toISOString(),

    source: 'voice',

    phone,

    transcript,

    customerName:
      String(
        body.customer_name ??
        body.name ??
        ''
      )
      .trim()
      .slice(0, 120),

    email:
      String(body.email ?? '')
      .trim()
      .slice(0, 180),

    rawProvider: {
      callSid:
        body.call_sid ??
        body.callSid ??
        null
    },

    config: {
      calendarId:
        String($env.GOOGLE_CALENDAR_ID || ''),

      timezone:
        String(
          $env.GOOGLE_CALENDAR_TIMEZONE ||
          'Asia/Kolkata'
        ),

      durationMinutes:
        Number(
          $env.GOOGLE_CALENDAR_APPOINTMENT_DURATION_MINUTES ||
          30
        )
    }
  }
}];

const base =
  $('Normalize • Correlation + Input Contract').first().json || $json;

let ai = {};

try {
  const raw =
    $json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

  ai =
    typeof raw === 'string'
      ? JSON.parse(raw)
      : (raw || {});
} catch (e) {
  ai = {};
}

const rawIntent = String(ai.intent || '').toLowerCase().trim();

const intent =
  rawIntent === 'reschedule'
    ? 'update'
    : ['create', 'update', 'cancel', 'chat'].includes(rawIntent)
      ? rawIntent
      : 'chat';

const confidence =
  Number.isFinite(Number(ai.confidence))
    ? Number(ai.confidence)
    : 0;

const clean = v =>
  v == null
    ? ''
    : String(v)
        .replace(/[<>]/g, '')
        .trim()
        .slice(0, 300);

const config = base.config || {};

const out = {
  ...base,

  intent,
  confidence,

  customerName:
    clean(ai.customer_name) ||
    base.customerName ||
    'Customer',

  email:
    clean(ai.email) ||
    base.email ||
    null,

  appointmentDate:
    clean(ai.appointment_date),

  appointmentTime:
    clean(ai.appointment_time),

  timezone:
    clean(ai.timezone) ||
    config.timezone ||
    'Asia/Kolkata',

  preferredHighway:
    clean(ai.preferred_highway),

  budget:
    clean(ai.budget),

  responseHint:
    clean(ai.response_hint),

  existingAppointmentDate:
    clean(ai.existing_appointment_date),

  existingAppointmentTime:
    clean(ai.existing_appointment_time)
};

const phoneOk =
  /^\+\d{10,15}$/.test(out.phone);

const dateOk =
  !out.appointmentDate ||
  /^\d{4}-\d{2}-\d{2}$/.test(out.appointmentDate);

const timeOk =
  !out.appointmentTime ||
  /^([01]\d|2[0-3]):[0-5]\d$/.test(
    out.appointmentTime
  );

const existingDateOk =
  !out.existingAppointmentDate ||
  /^\d{4}-\d{2}-\d{2}$/.test(
    out.existingAppointmentDate
  );

const existingTimeOk =
  !out.existingAppointmentTime ||
  /^([01]\d|2[0-3]):[0-5]\d$/.test(
    out.existingAppointmentTime
  );

out.validationError = null;
out.safeToExecute = true;

/*
 * PHONE
 */
if (!phoneOk) {

  out.safeToExecute = false;
  out.validationError = 'INVALID_PHONE';

/*
 * CONFIDENCE
 */
} else if (
  confidence < 0.70 &&
  intent !== 'chat'
) {

  out.safeToExecute = false;
  out.validationError = 'LOW_CONFIDENCE';

/*
 * CREATE / UPDATE
 */
} else if (
  (intent === 'create' || intent === 'update') &&
  (!out.appointmentDate || !out.appointmentTime)
) {

  out.safeToExecute = false;
  out.validationError = 'DATE_TIME_REQUIRED';

/*
 * CANCEL REQUIRES EXISTING APPOINTMENT SLOT
 */
} else if (
  intent === 'cancel' &&
  (!out.existingAppointmentDate || !out.existingAppointmentTime)
) {

  out.safeToExecute = false;
  out.validationError = 'EXISTING_APPOINTMENT_REQUIRED';

/*
 * DATE / TIME FORMAT
 */
} else if (
  !dateOk ||
  !timeOk ||
  !existingDateOk ||
  !existingTimeOk
) {

  out.safeToExecute = false;
  out.validationError = 'INVALID_DATE_TIME_FORMAT';

/*
 * GHL CONFIG
 */
} else if (
  ['create', 'update', 'cancel'].includes(intent) &&
  (!config.calendarId)
) {

  out.safeToExecute = false;
  out.validationError = 'GOOGLE_CALENDAR_CONFIG_MISSING';
}

return [{
  json: out
}];

const base = $('Validator • Structured Output + Business Rules').first().json;
const events = $input.all().map(i => i.json || {});

const targetDate = base.existingAppointmentDate || base.appointmentDate || '';
const targetTime = base.existingAppointmentTime || base.appointmentTime || '';

function clean(v) {
  return String(v ?? '').trim();
}
function eventMatches(e) {
  if (!e || !e.id) return false;
  const hay = [
    e.description, e.summary,
    ...(Array.isArray(e.attendees) ? e.attendees.map(a => a.email) : [])
  ].filter(Boolean).join(' ').toLowerCase();
  const phone = clean(base.phone).toLowerCase();
  return phone && hay.includes(phone);
}
const candidates = events.filter(eventMatches);
const active = candidates[0] || null;

function toIso(dateStr,timeStr,tz) {
  if (!dateStr || !timeStr) return null;
  const m = String(timeStr).match(/^([01]\d|2[0-3]):([0-5]\d)$/);
  if (!m) return null;
  // Asia/Kolkata is the default business timezone. For other configured zones,
  // the workflow relies on the ISO value supplied by the model only when explicit.
  if (tz === 'Asia/Kolkata') {
    const [y,mo,d] = dateStr.split('-').map(Number);
    const [hh,mm] = timeStr.split(':').map(Number);
    const utc = Date.UTC(y,mo-1,d,hh,mm) - (5.5*60*60*1000);
    return new Date(utc).toISOString();
  }
  return `${dateStr}T${timeStr}:00`;
}

const requestedDate = base.intent === 'cancel'
  ? base.existingAppointmentDate
  : base.appointmentDate;
const requestedTime = base.intent === 'cancel'
  ? base.existingAppointmentTime
  : base.appointmentTime;

const requestedStart = toIso(requestedDate, requestedTime, base.timezone);
const requestedEnd = requestedStart
  ? new Date(Date.parse(requestedStart) + Number(base.config.durationMinutes||30)*60000).toISOString()
  : null;

return [{
  json: {
    ...base,
    activeEventId: active?.id || null,
    activeEvent: active,
    requestedStart,
    requestedEnd,
    activeEventFound: !!active
  }
}];

const base = $('Resolver • Google Calendar Appointment + Requested Slot').first().json;
const events = Array.isArray($json) ? $json : [$json];
const start = Date.parse(base.requestedStart);
const end = Date.parse(base.requestedEnd);
const duration = Number(base.config.durationMinutes || 30);

const conflicts = events.filter(e => {
  if (!e || !e.id || e.id === base.activeEventId) return false;
  const s = Date.parse(e.start?.dateTime || e.start?.date || '');
  const en = Date.parse(e.end?.dateTime || e.end?.date || '');
  return Number.isFinite(s) && Number.isFinite(en) && s < end && en > start;
});

const localHour = Number(new Intl.DateTimeFormat('en-GB',{timeZone:base.timezone,hour:'2-digit',hourCycle:'h23'}).format(new Date(start)));
const localMinute = Number(new Intl.DateTimeFormat('en-GB',{timeZone:base.timezone,minute:'2-digit'}).format(new Date(start)));
const minutes = localHour*60+localMinute;
const withinBusiness = minutes >= 600 && minutes + duration <= 1140;
const notPast = start > Date.now() + 15*60000;

return [{json:{
  ...base,
  slotAvailable: conflicts.length === 0 && withinBusiness && notPast,
  slotReason: conflicts.length ? 'SLOT_CONFLICT' : (!withinBusiness ? 'OUTSIDE_BUSINESS_HOURS' : (!notPast ? 'MINIMUM_NOTICE' : 'OK')),
  conflictCount: conflicts.length
}}];

const base = $('Resolver • Google Calendar Appointment + Requested Slot').first().json;
const intent = base.intent;
const inputs = $input.all();

let verified = false;
let eventId = base.activeEventId || null;
let source = {};

if (intent === 'cancel') {
  const events = inputs.map(i => i.json || {});
  verified = !events.some(e => e?.id === base.activeEventId);
  source = {remainingEvents: events.map(e => ({id:e.id, summary:e.summary, start:e.start, end:e.end}))};
} else {
  source = inputs[0]?.json || {};
  eventId = source.id || null;
  const start = source.start?.dateTime || source.start?.date || '';
  const end = source.end?.dateTime || source.end?.date || '';
  verified =
    !!source.id &&
    Date.parse(start) === Date.parse(base.requestedStart) &&
    Date.parse(end) === Date.parse(base.requestedEnd);
}

return [{json:{...base, verified, calendarEventId:eventId, providerResponse:source}}];

const base =
  $('Resolver • Google Calendar Appointment + Requested Slot').first()?.json ||
  $('Validator • Structured Output + Business Rules').first()?.json ||
  $json;

const source = $json || {};
let operationStatus = 'ERROR';
let message = 'I could not confirm that calendar change. Please try again.';
let eventId = source.calendarEventId || base.activeEventId || null;

if (base.intent === 'chat') {
  const text = source.candidates?.[0]?.content?.parts?.[0]?.text;
  operationStatus = 'CHAT';
  message = typeof text === 'string' && text.trim()
    ? text.trim().slice(0, 1200)
    : 'I can help with appointments. Please tell me whether you want to book, reschedule, or cancel an appointment.';
} else if (base.intent === 'create' && source.verified === true) {
  operationStatus = 'SUCCESS';
  message = 'Your appointment has been booked successfully.';
} else if (base.intent === 'update' && source.verified === true) {
  operationStatus = 'SUCCESS';
  message = 'Your appointment has been rescheduled successfully.';
} else if (base.intent === 'cancel' && source.verified === true) {
  operationStatus = 'SUCCESS';
  message = 'Your appointment has been cancelled successfully.';
} else if (source.slotAvailable === false) {
  operationStatus = 'CONFLICT';
  message = 'That time is not available. Please choose another time.';
} else if (base.validationError) {
  operationStatus = 'VALIDATION_ERROR';
  message = 'I need a little more information before I can make that appointment change.';
}

const voice = message.replace(/[^\x20-\x7E]/g,' ').replace(/\s+/g,' ').trim();
const xml = voice.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

return [{json:{
  ...base,
  operationStatus,
  calendarEventId:eventId,
  responseText:message,
  voiceResponseText:voice,
  twiml:`<?xml version="1.0" encoding="UTF-8"?><Response><Say>${xml}</Say></Response>`,
  completedAt:new Date().toISOString()
}}];
